}
function blockFor(a){const known=props.page.blocks.find(b=>a.blockId!==undefined&&b.id===a.blockId);if(known)return known;const r=a.rects[0],x=r.x+r.width/2,y=r.y+r.height/2;return props.page.blocks.find(b=>{const box=(a.origin==='translation'?b.translatedBox:b.sourceBox)||b;return x>=box.x&&x<=box.x+box.width&&y>=box.y&&y<=box.y+box.height;});}
