// Measure the displayed page once for a shared margin rail, including async PDF text.
const noteRail=computed(()=>{
 layoutVersion.value;
 const host=props.host(),bounds=host?.getBoundingClientRect();
 let right=0;
 if(bounds)for(const span of host.querySelectorAll('.reading-text-layer span,.reading-paragraph .paragraph-text')){
  if(!span.getClientRects().length)continue;
  const range=document.createRange();range.selectNodeContents(span);
  for(const r of range.getClientRects())if(r.width>0&&r.height>0)right=Math.max(right,(r.right-bounds.left)/props.zoom);
 }
