function highlightPosition(r,a){const padding=2/props.zoom,gap=4/props.zoom,previous=a.rects.filter(b=>b.y<r.y-1).sort((a,b)=>b.y-a.y)[0],next=a.rects.filter(b=>b.y>r.y+1).sort((a,b)=>a.y-b.y)[0];const x=Math.max(0,r.x-padding),y=Math.max(0,r.y-padding,previous?(previous.y+previous.height+r.y)/2+gap/2:0),bottom=Math.min(props.page.height,r.y+r.height+padding,next?(r.y+r.height+next.y)/2-gap/2:Infinity);return position({x,y,width:Math.min(props.page.width,r.x+r.width+padding)-x,height:Math.max(1,bottom-y)});}
function point(){
 layoutVersion.value;
