function touch(){clearTimeout(timer);timer=setTimeout(()=>toolbar.value=false,3000);}
function capture(event){if(event.target.closest('.annotation-ui,.annotation-mark'))return;setTimeout(()=>{const s=window.getSelection();if(!s?.rangeCount||s.isCollapsed){toolbar.value=false;return;}const range=s.getRangeAt(0),host=props.host();if(!host?.contains(range.startContainer)||!host.contains(range.endContainer))return;const bounds=host.getBoundingClientRect(),paragraph=range.startContainer.parentElement?.closest('[data-block-id]'),origin=paragraph||(props.translated&&props.page.mathDocument)?'translation':'source';const raw=[...range.getClientRects()].filter(r=>r.width>1&&r.height>1);const lines=[];for(const r of raw){const last=lines.at(-1);if(last&&Math.abs(last.top-r.top)<2){last.right=Math.max(last.right,r.right);last.bottom=Math.max(last.bottom,r.bottom);}else lines.push({left:r.left,right:r.right,top:r.top,bottom:r.bottom});}const rects=annotationLineRects(lines.map(r=>({x:(r.left-bounds.left)/props.zoom,y:(r.top-bounds.top)/props.zoom,width:(r.right-r.left)/props.zoom,height:(r.bottom-r.top)/props.zoom})));if(!rects.length)return;const middle=rects[0];const block=paragraph?props.page.blocks.find(b=>String(b.id)===paragraph.dataset.blockId):props.page.blocks.find(b=>{const box=(origin==='translation'?b.translatedBox:b.sourceBox)||b;return middle.x>=box.x&&middle.x<=box.x+box.width&&middle.y>=box.y&&middle.y<=box.y+box.height;});const sourceBox=block?.sourceBox||block,translationBox=block?.translatedBox||block;const end=box=>box?{x:Math.max(0,Math.min(props.page.width-14,box.x+box.width-14)),y:Math.max(0,Math.min(props.page.height-14,box.y+box.height)),width:14,height:14}:rects.at(-1);selection.value={page:props.page.number,origin,text:s.toString(),rects,blockId:block?.id,sourceRect:end(sourceBox),translationRect:end(translationBox)};toolbar.value=true;opened.value=null;menu.value=null;touch();},0);}
function persist(list){emit('change',list);}
function add(kind,color,comment=''){const existing=props.annotations.find(a=>a.id===selection.value?.id);if(existing){const a={...existing,color,modifiedAt:new Date().toISOString()};persist(props.annotations.map(b=>b.id===a.id?a:b));focused.value=a;selection.value=a;touch();return;}const a={...selection.value,id:crypto.randomUUID(),kind,color,comment,animateUntil:performance.now()+highlightDuration,createdAt:new Date().toISOString()};persist([...props.annotations,a]);focused.value=a;toolbar.value=false;selection.value=null;window.getSelection()?.removeAllRanges();if(kind==='highlight'){try{const counts=JSON.parse(localStorage.getItem('highlightColors')||'{}').counts||{};counts[color]=(counts[color]||0)+1;const custom=Object.keys(counts).filter(c=>!colors.includes(c.toUpperCase()));favorite.value=custom.sort((a,b)=>counts[b]-counts[a])[0]||'#00FFFF';localStorage.setItem('highlightColors',JSON.stringify({counts,favorite:favorite.value}));}catch{}}}
async function comment(a){loadingComment=true;editor.value=a?{...a}:{...selection.value,id:crypto.randomUUID(),kind:'comment',color:'#fff36a',comment:'',createdAt:new Date().toISOString()};draft.value=a?.comment||'';toolbar.value=false;await nextTick();loadingComment=false;document.querySelector('.annotation-editor textarea')?.focus();}
function saveComment(){if(!editor.value||loadingComment||!draft.value.trim())return;const a={...editor.value,comment:draft.value,modifiedAt:new Date().toISOString()};persist([...props.annotations.filter(b=>b.id!==a.id),a]);}
watch(draft,saveComment);
function commit(){if(!draft.value.trim())return;saveComment();focused.value=editor.value;editor.value=null;selection.value=null;window.getSelection()?.removeAllRanges();}
