function key(e){if(e.repeat&&['Delete','Backspace'].includes(e.key))return;if(assistance.value){if(e.key==='Escape'){assistController?.abort();assistance.value=null;e.preventDefault();}return;}if(editor.value){if(e.key==='Tab'){const controls=[...document.querySelectorAll('.annotation-editor textarea,.annotation-editor button')].filter(el=>!el.disabled);const index=controls.indexOf(document.activeElement);controls[(index+(e.shiftKey?-1:1)+controls.length)%controls.length]?.focus();e.preventDefault();}if(e.key==='Escape'){editor.value=null;e.preventDefault();}if(e.key==='Enter'&&(e.metaKey||e.ctrlKey)){commit();e.preventDefault();}return;}if(e.target.closest?.('input,textarea,[contenteditable]'))return;if(!e.defaultPrevented&&!e.repeat&&!e.isComposing&&!e.metaKey&&!e.ctrlKey&&!e.altKey&&!e.shiftKey&&toolbar.value&&selection.value&&!menu.value&&!confirming.value&&['1','2','3','4'].includes(e.key)){e.preventDefault();if(e.key==='4')void comment(selection.value.id?selection.value:undefined);else add('highlight',colors[Number(e.key)-1]);return;}if(['Delete','Backspace'].includes(e.key)&&visible.value.length&&!focused.value)hint();if(['Delete','Backspace'].includes(e.key)&&focused.value){e.preventDefault();hint();const now=Date.now();if(now-deleteTime<600){remove(focused.value);deleteTime=0;}else deleteTime=now;}if(e.key==='Escape'){toolbar.value=false;menu.value=null;opened.value=null;confirming.value=null;}}
