async function action(name){const a=menu.value.a;menu.value=null;try{if(name==='删除'){confirming.value=a;return;}if(name==='修改'){await comment(a);return;}const text=[a.text,a.comment].filter(Boolean).join('\n\n');if(name==='分享'&&window.previewAnnotations?.share&&await window.previewAnnotations.share(text))return;if(name==='分享'&&navigator.share){await navigator.share({text});return;}if(name==='Hand over to AI'){if(!window.previewAnnotations?.handover)throw Error('请在桌面客户端中交接到本机 ChatGPT 或 Claude。');const result=await window.previewAnnotations.handover(text);if(!result.cancelled)emit('notice',{text:`已打开 ${result.client}，内容已复制，请粘贴并发送`,...pointer.value});return;}if(name==='Paraphrase'){assistController?.abort();const controller=assistController=new AbortController();const result={title:'Paraphrase',text:'',busy:true,error:''};assistance.value=result;try{const response=await fetch('/api/reading-assist',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'paraphrase',text:a.text,comment:a.comment}),signal:controller.signal});const data=await response.json();if(!response.ok)throw Error(data.error||'请求失败');result.text=data.text;}catch(e){if(e.name!=='AbortError')result.error=e.message;}finally{result.busy=false;if(!controller.signal.aborted)assistance.value={...result};}return;}await (window.previewClipboard?.writeText||navigator.clipboard.writeText.bind(navigator.clipboard))(text);emit('notice',{text:name==='分享'?'已复制分享内容':'已复制',...pointer.value});}catch(e){if(e.name!=='AbortError')emit('notice',{text:'无法完成操作：'+e.message,...pointer.value});}}
