onBeforeUnmount(()=>{textObserver?.disconnect();popupObserver?.disconnect();cancelAnimationFrame(layoutFrame);window.removeEventListener('resize',updatePopupLayout);window.removeEventListener('scroll',updatePopupLayout,true);cancelAnimationFrame(motionFrame);eraseTimers.forEach(clearTimeout);eraseTimers.clear();assistController?.abort();clearTimeout(timer);document.removeEventListener('pointerup',capture);document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',key);document.removeEventListener('pointermove',observePointer);});
